<script setup>
import { ref } from 'vue';
const open = ref(false), loggedIn = ref(false), token = ref(''), username = ref(''), password = ref(''), busy = ref(false), message = ref(''), image = ref(null);
const form = ref({ name:'', cuisine:'Filipino', address:'', price:'PP', rating:0, description:'' });
async function login(){ busy.value=true; message.value=''; try { const r=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value})}); const d=await r.json(); if(!r.ok) throw new Error(d.message||'Login failed'); token.value=d.token; loggedIn.value=true; } catch(e){message.value=e.message} finally{busy.value=false} }
async function save(){ busy.value=true; message.value=''; try { const data=new FormData(); Object.entries(form.value).forEach(([k,v])=>data.append(k,v)); if(image.value) data.append('image',image.value); const r=await fetch('/api/admin/restaurants',{method:'POST',headers:{Authorization:`Bearer ${token.value}`},body:data}); const d=await r.json(); if(!r.ok) throw new Error(d.message||'Could not add restaurant'); message.value='Restaurant added! Refreshing the list…'; setTimeout(()=>location.reload(),700); }catch(e){message.value=e.message}finally{busy.value=false} }
</script>
<template>
  <button @click="open=true" aria-label="Add restaurant" title="Admin: add restaurant" class="inline-flex h-9 w-9 items-center justify-center rounded-lg border border-border bg-card text-xl font-semibold text-foreground hover:bg-secondary">+</button>
  <div v-if="open" class="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4" @click.self="open=false">
    <section class="w-full max-w-lg max-h-[90vh] overflow-y-auto rounded-2xl bg-background p-6 shadow-2xl">
      <div class="mb-5 flex items-center justify-between"><h2 class="font-display text-2xl font-bold">{{ loggedIn ? 'Add a restaurant' : 'Admin login' }}</h2><button class="text-2xl" @click="open=false">×</button></div>
      <form v-if="!loggedIn" class="space-y-4" @submit.prevent="login"><label class="block text-sm">Username<input v-model="username" required autocomplete="username" class="mt-1 w-full rounded-lg border border-border bg-card p-3"></label><label class="block text-sm">Password<input v-model="password" type="password" required autocomplete="current-password" class="mt-1 w-full rounded-lg border border-border bg-card p-3"></label><button :disabled="busy" class="w-full rounded-lg bg-primary p-3 font-medium text-primary-foreground">{{busy?'Signing in…':'Login'}}</button></form>
      <form v-else class="space-y-3" @submit.prevent="save"><label class="block text-sm">Restaurant name *<input v-model="form.name" required class="mt-1 w-full rounded-lg border border-border bg-card p-3"></label><label class="block text-sm">Cuisine *<input v-model="form.cuisine" required placeholder="Kapampangan, Filipino…" class="mt-1 w-full rounded-lg border border-border bg-card p-3"></label><label class="block text-sm">Address *<input v-model="form.address" required class="mt-1 w-full rounded-lg border border-border bg-card p-3"></label><label class="block text-sm">Price range<select v-model="form.price" class="mt-1 w-full rounded-lg border border-border bg-card p-3"><option value="P">₱ Budget</option><option value="PP">₱₱ Moderate</option><option value="PPP">₱₱₱ Premium</option></select></label><label class="block text-sm">Rating (0–5)<input v-model.number="form.rating" type="number" min="0" max="5" step="0.1" class="mt-1 w-full rounded-lg border border-border bg-card p-3"></label><label class="block text-sm">Description<textarea v-model="form.description" rows="3" class="mt-1 w-full rounded-lg border border-border bg-card p-3"></textarea></label><label class="block text-sm">Restaurant photo (PNG, max 3 MB) *<input required type="file" accept="image/png,.png" class="mt-1 block w-full text-sm" @change="image=$event.target.files?.[0]||null"></label><button :disabled="busy" class="w-full rounded-lg bg-primary p-3 font-medium text-primary-foreground">{{busy?'Saving…':'Save restaurant'}}</button></form>
      <p v-if="message" class="mt-4 rounded-lg bg-secondary p-3 text-sm" role="status">{{message}}</p>
    </section>
  </div>
</template>
